sed -i '/fun createPlaylist/i \    fun getPlaylistMediaFiles(playlistId: Long): kotlinx.coroutines.flow.Flow<List<MediaModel>> {\n        return kotlinx.coroutines.flow.combine(\n            repository.getMediaForPlaylist(playlistId),\n            audioFiles,\n            videoFiles\n        ) { crossRefs, audios, videos ->\n            val paths = crossRefs.map { it.filePath }\n            val allMedia = audios + videos\n            allMedia.filter { it.filePath in paths }\n        }\n    }\n' app/src/main/java/com/example/ui/MediaViewModel.kt
